import sys

def search_brute(matrix, target):
    m, n = len(matrix), len(matrix[0])
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == target:
                return True
    return False

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    m, n = int(data[0]), int(data[1])
    matrix = []
    idx = 2
    for _ in range(m):
        matrix.append([int(x) for x in data[idx:idx + n]])
        idx += n
    target = int(data[idx])
    print('true' if search_brute(matrix, target) else 'false')

import sys

def search_opt(matrix, target):
    m, n = len(matrix), len(matrix[0])
    i, j = 0, n - 1
    while i < m and j >= 0:
        if matrix[i][j] == target: return True
        if matrix[i][j] < target:
            i += 1
        else:
            j -= 1
    return False

